declare namespace custom = "http://www.example.org/custom";
declare function custom:is-valid-id-format($id as xs:string) as xs:boolean { (       matches(normalize-space($id), '^[A-Za-z0-9+\-_/]+$') and       not(matches($id, ' ')) and       not(starts-with($id, ' ')) and       not(ends-with($id, ' '))       ) };
declare function custom:is-valid-date-format($date as xs:string) as xs:boolean { let $isFormatValid := (matches($date, '^20\d{2}(0[1-9]|1[0-2])(0[1-9]|[12]\d|3[01])$')) return let $year := (xs:decimal(substring($date, 1, 4))) return let $month := (xs:decimal(substring($date, 5, 2))) return let $day := (xs:decimal(substring($date, 7, 2))) return let $isLeapYear := (($year mod 4 = 0 and $year mod 100 != 0) or ($year mod 400 = 0)) return let $maxDay := (       if ($month = (1, 3, 5, 7, 8, 10, 12)) then 31       else if ($month = (4, 6, 9, 11)) then 30       else if ($month = 2 and $isLeapYear) then 29       else if ($month = 2) then 28       else 0) return ($isFormatValid and $day le $maxDay) };
declare function custom:is-valid-document-type-code($code as xs:string) as xs:boolean { let $custom_document-type-codes := ('380 389 393 501 386 500 384 471 472 473 261 262 381 396 502 503') return ($code = tokenize($custom_document-type-codes, '\s+')) };
declare function custom:is-valid-billing-mode($code as xs:string) as xs:boolean { let $custom_billing-modes := ('B1 S1 M1 B2 S2 S3 M2 B4 S4 M4 S5 S6 B7 S7 B8 S8 M8 B9 S9 M9') return ($code = tokenize($custom_billing-modes, '\s+')) };
declare function custom:check-siret-siren-coherence($siret as xs:string?, $siren as xs:string?) as xs:boolean { (matches($siret, '^\d{14}$') and substring($siret, 1, 9) = $siren) };
declare function custom:is-valid-bar-treatment($value as xs:string?) as xs:boolean { ($value = ('B2B', 'B2BINT', 'B2C', 'OUTOFSCOPE', 'ARCHIVEONLY')) };
