declare function custom:is-valid-invoice-action-code($code as xs:string) as xs:boolean { let $custom_invoice-action-codes := ('NOA PIN NIN CNF CNP CNA OTH') return ($code = tokenize($custom_invoice-action-codes, '\s+')) };
